SELECT a.Dept_Name, b.First_Name
FROM Department a
LEFT JOIN Employee b ON a.Manager_ID = b.Employee_ID;

SELECT b.First_Name, b.Dept_ID, b.Salary_Amount
FROM Employee b
WHERE b.Salary_Amount > (SELECT AVG(x.Salary_Amount) FROM Employee x WHERE x.Dept_ID = b.Dept_ID);

SELECT b.First_Name, c.Grade_Label
FROM Employee b
JOIN Salary_Grade c ON b.Salary_Amount BETWEEN c.Min_Salary AND c.Max_Salary;

SELECT a.Dept_Name
FROM Department a
WHERE NOT EXISTS (
  SELECT 1 FROM Project b
  WHERE b.Dept_ID = a.Dept_ID AND b.Status = 'Active'
);

DELIMITER $$
CREATE TRIGGER trg_check_department
BEFORE DELETE ON department
FOR EACH ROW
BEGIN
  IF EXISTS (SELECT 1 FROM employee WHERE Dept_ID = OLD.Dept_ID) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Cannot delete a department that still has employees.';
  END IF;
END $$
DELIMITER ;

DELIMITER $$
CREATE FUNCTION GetAnnualSalary(p_id INT)
RETURNS DECIMAL(10,2)
DETERMINISTIC
READS SQL DATA
BEGIN
  DECLARE v_salary DECIMAL(10,2);
  SELECT Salary_Amount INTO v_salary FROM Employee WHERE Employee_ID = p_id;
  RETURN v_salary * 12;
END $$
DELIMITER ;
